_CORE_SRC = '# Action format: "[(from_node, to_node, count), ...]"\n# Payout: "served_i = capacity_i * demand / max(total_capacity, demand)",\n# where capacity_i = drones_i * 5.\n# Cost: "UPKEEP = 2.0" per drone away from its own base after each turn\'s\n# moves. Each drone moves at most one edge, using start-of-turn availability.\n\nimport heapq\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 100\nDRONE_CAPACITY = 5\nUPKEEP = 2.0\n\n\ndef served(own, opponent, demand):\n    """The exact revenue formula, including the zero-demand case."""\n    capacity = DRONE_CAPACITY * own\n    total = DRONE_CAPACITY * (own + opponent)\n    denominator = max(total, demand)\n    return capacity * demand / denominator if denominator > 0 else 0.0\n\n\ndef score_difference(own, opponent, demand):\n    return served(own, opponent, demand) - served(opponent, own, demand)\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for u, v in edges:\n        adjacency[u].append(v)\n        adjacency[v].append(u)\n    for neighbors in adjacency:\n        neighbors.sort()\n\n    distances = []\n    for source in range(n):\n        row = [-1] * n\n        row[source] = 0\n        queue = deque([source])\n        while queue:\n            u = queue.popleft()\n            for v in adjacency[u]:\n                if row[v] < 0:\n                    row[v] = row[u] + 1\n                    queue.append(v)\n        distances.append(row)\n\n    next_hop = [[-1] * n for _ in range(n)]\n    for source in range(n):\n        for target in range(n):\n            if distances[source][target] > 0:\n                next_hop[source][target] = next(\n                    v for v in adjacency[source]\n                    if distances[v][target] == distances[source][target] - 1\n                )\n    return adjacency, distances, next_hop\n\n\ndef legal_action(have, want, adjacency, distances, next_hop):\n    """Match closest surpluses first, then validate against original counts."""\n    n = len(have)\n    surplus = [max(0, have[v] - want[v]) for v in range(n)]\n    deficit = [max(0, want[v] - have[v]) for v in range(n)]\n    pairs = sorted(\n        (distances[s][t], s, t)\n        for s in range(n) if surplus[s]\n        for t in range(n) if deficit[t] and distances[s][t] > 0\n    )\n    aggregate = {}\n    for _, source, target in pairs:\n        count = min(surplus[source], deficit[target])\n        if count <= 0:\n            continue\n        hop = next_hop[source][target]\n        if hop < 0:\n            continue\n        surplus[source] -= count\n        deficit[target] -= count\n        key = (source, hop)\n        aggregate[key] = aggregate.get(key, 0) + count\n\n    available = list(have)\n    action = []\n    for (source, target), requested in sorted(aggregate.items()):\n        if not (0 <= source < n and 0 <= target < n):\n            continue\n        if target not in adjacency[source]:\n            continue\n        count = min(int(requested), int(available[source]))\n        if count > 0:\n            action.append((int(source), int(target), int(count)))\n            available[source] -= count\n    return action\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_data = None\n        self.previous_want = None\n        self.bad_reports = 0\n\n    def plan(self, obs, deadline):\n        adjacency, distances, next_hop = self.map_data\n        n = len(adjacency)\n        have = list(obs["player_drones"])\n        opponent = obs["opponent_drones"]\n        base = int(obs["player_base"])\n        enemy_base = int(obs["opponent_base"])\n        remaining = max(0, N_TURNS - int(obs.get("turn", 0)))\n        if remaining == 0:\n            return have\n\n        # A rolling economic horizon avoids assuming the current opponent\n        # positions and an uncertain demand tail persist for the whole match.\n        horizon = min(12, remaining)\n        weights = [0.96 ** k for k in range(horizon)]\n        total_weight = sum(weights)\n        forecasts = obs.get("demand_forecast", [])\n        values = []\n        for v in range(n):\n            row = forecasts[v] if v < len(forecasts) else []\n            if not row:\n                values.append([0.0] * horizon)\n                continue\n            # Beyond the exact forecast use a conservative smoothed endpoint.\n            tail = 0.65 * float(row[-1]) + 0.35 * (\n                sum(float(x) for x in row) / len(row)\n            )\n            values.append([\n                float(row[k]) if k < len(row) else tail\n                for k in range(horizon)\n            ])\n\n        sources = [s for s in range(n) if have[s] > 0]\n        targets = [v for v in range(n) if v != base and v != enemy_base]\n        available = list(have)\n        want = [0] * n\n\n        # Each unassigned unit has the fallback of returning home. Travel to\n        # home costs upkeep until (but not including) its arrival payout.\n        return_cost = {}\n        for source in sources:\n            travel = max(0, distances[source][base] - 1)\n            return_cost[source] = UPKEEP * sum(weights[:travel])\n\n        # Marginal score differences count both our revenue and enemy denial.\n        marginal_cache = {}\n\n        def marginal_series(target, count):\n            key = (target, count)\n            if key not in marginal_cache:\n                enemy = opponent[target]\n                marginal_cache[key] = [\n                    score_difference(count + 1, enemy, d)\n                    - score_difference(count, enemy, d)\n                    for d in values[target]\n                ]\n            return marginal_cache[key]\n\n        previous = self.previous_want\n        conservative = self.bad_reports >= 2\n\n        def gain(source, target, count):\n            distance = distances[source][target]\n            arrival = max(0, distance - 1)\n            if distance < 0 or arrival >= horizon:\n                return -1.0e20\n            marginal = marginal_series(target, count)\n            revenue = sum(\n                weights[k] * marginal[k] for k in range(arrival, horizon)\n            )\n            result = revenue - UPKEEP * total_weight + return_cost[source]\n            # Small transaction friction and a target-retention bonus prevent\n            # chasing minor changes in the moving forecast.\n            if source != target:\n                result -= 0.65 + 0.25 * distance\n            if previous is not None and count < previous[target]:\n                result += 0.8\n            if conservative and distance > 1:\n                result -= 2.0 * distance\n            return result\n\n        heap = []\n        for source in sources:\n            for target in targets:\n                g = gain(source, target, 0)\n                if g > 0:\n                    heapq.heappush(heap, (-g, source, target, 0))\n\n        # Lazy heap updates: marginal gains decrease as a node fills.\n        # Units at a target naturally receive the best travel-adjusted bids.\n        while heap:\n            if time.perf_counter() >= deadline:\n                break\n            negative_gain, source, target, version = heapq.heappop(heap)\n            if available[source] <= 0:\n                continue\n            if version != want[target]:\n                g = gain(source, target, want[target])\n                if g > 0:\n                    heapq.heappush(heap, (-g, source, target, want[target]))\n                continue\n            if negative_gain >= 0:\n                break\n            available[source] -= 1\n            want[target] += 1\n            if available[source] > 0:\n                g = gain(source, target, want[target])\n                if g > 0:\n                    heapq.heappush(heap, (-g, source, target, want[target]))\n\n        # Unprofitable or unprocessed units are assigned to the free base.\n        want[base] += sum(available)\n        return want\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.58 * TIME_BUDGET)\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return []\n\n        if self.map_data is None:\n            self.map_data = preprocess_map(n, obs.get("edges", []))\n\n        if (obs.get("n_invalid_actions_last_turn", 0) > 0\n                or not obs.get("action_format_correct_last_turn", True)):\n            self.bad_reports += 1\n\n        have = obs.get("player_drones", [])\n        if len(have) != n or sum(have) <= 0:\n            return []\n        want = self.plan(obs, deadline)\n        adjacency, distances, next_hop = self.map_data\n        action = legal_action(have, want, adjacency, distances, next_hop)\n        self.previous_want = list(want)\n        return action\n'
_CORE_CLASS = 'Strategy'
